<script>
  (() => { const tabs=[...document.querySelectorAll('[data-settings-tab]')]; const panels=[...document.querySelectorAll('.settings-stack > .setting-card')]; const activate=id=>{const selected=document.getElementById(id)||panels[0];panels.forEach(panel=>{panel.hidden=panel!==selected;});tabs.forEach(tab=>tab.classList.toggle('active',tab.dataset.settingsTab===selected.id));if(history.replaceState)history.replaceState(null,'','#'+selected.id);};tabs.forEach(tab=>tab.addEventListener('click',event=>{event.preventDefault();activate(tab.dataset.settingsTab);}));activate(location.hash.substring(1)||new URLSearchParams(location.search).get('tab')||'profile'); })();
</script>
<script>
  (() => { const body=document.body; const toggle=document.getElementById('theme-toggle'); const description=document.getElementById('theme-description'); const apply=dark=>{body.classList.toggle('dark-mode',dark);toggle.innerHTML=dark?'<i class="bi bi-sun"></i> Mode terang':'<i class="bi bi-moon-stars"></i> Mode gelap';description.textContent=dark?'Mode gelap dengan kontras rendah':'Mode terang dengan aksen biru';localStorage.setItem('titip-kilat-theme',dark?'dark':'light');}; const saved=localStorage.getItem('titip-kilat-theme'); apply(saved==='dark'); toggle.addEventListener('click',()=>apply(!body.classList.contains('dark-mode'))); })();
</script>
<script>
  (() => { document.querySelectorAll('[data-confirm]').forEach(form => form.addEventListener('submit', event => { if (!window.confirm(form.dataset.confirm)) event.preventDefault(); })); })();
</script>
